<?php use CmuLms\View; $title='Course management'; include __DIR__.'/../layout/header.php'; ?>
<section class="card"><h1>Course management</h1><p>Create subjects only with an administrator-configured academic term.</p><form method="post" action="?route=course-create" class="grid"><?=View::csrfField()?><label>Course code<input name="code" required></label><label>Course title<input name="title" required></label><label>Section code<input name="section_code"></label><label>Teacher<select name="teacher_id" required><?php foreach($teachers as $t):?><option value="<?=View::e($t['id'])?>"><?=View::e($t['name'])?> (<?=View::e($t['id_number'])?>)</option><?php endforeach;?></select></label><label>Academic year<select name="academic_year" required><?php foreach($terms as $t): if(empty($t['active']))continue; ?><option value="<?=View::e($t['academic_year'])?>"><?=View::e($t['academic_year'])?></option><?php endforeach;?></select></label><label>Semester<select name="semester" required><option value="1st">1st semester</option><option value="2nd">2nd semester</option></select></label><label>Description<textarea name="description"></textarea></label><button>Create course</button></form></section>
<section class="card"><h2>Academic terms</h2><form method="post" action="?route=term-create" class="grid"><?=View::csrfField()?><label>Academic year<input name="academic_year" placeholder="2027-2028" pattern="[0-9]{4}-[0-9]{4}" required></label><label>Semester<select name="semester"><option value="1st">1st semester</option><option value="2nd">2nd semester</option></select></label><button>Add term</button></form><?php foreach($terms as $t):?><div style="display:flex;justify-content:space-between;gap:1rem;align-items:center"><span class="badge"><?=View::e($t['academic_year'])?> · <?=View::e($t['semester'])?> · <?=!empty($t['active'])?'Active':'Inactive'?></span><form method="post" action="?route=term-toggle"><?=View::csrfField()?><input type="hidden" name="term_id" value="<?=View::e($t['id'])?>"><input type="hidden" name="active" value="<?=empty($t['active'])?'1':'0'?>"><button><?=empty($t['active'])?'Activate':'Deactivate'?></button></form></div><?php endforeach;?></section>
<section class="card"><h2>Bulk student enrollment</h2><p>New accounts receive the temporary password <strong>ChangeMe!</strong>.</p><form method="post" action="?route=student-import" enctype="multipart/form-data" class="grid"><?=View::csrfField()?><label>Course<select name="course_id" required><?php foreach($courses as $c):?><option value="<?=View::e($c['id'])?>"><?=View::e($c['code'])?> · <?=View::e($c['section_code'])?></option><?php endforeach;?></select></label><label>CSV file<input type="file" name="file" accept=".csv" required></label><label>Section override<input name="section_code"></label><button>Import and enroll students</button></form></section>
<section class="card"><h2>Existing courses</h2><div style="overflow-x:auto"><table><tr><th>Code</th><th>Title</th><th>Teacher</th><th>Section</th><th>Academic term</th><th>Students</th></tr><?php foreach($courses as $c):?><tr><td><?=View::e($c['code'])?></td><td><?=View::e($c['title'])?></td><td><?=View::e($c['teacher_name'])?></td><td><?=View::e($c['section_code'])?></td><td><?=View::e($c['academic_year'])?> · <?=View::e($c['semester'])?></td><td><?=View::e($c['students'])?></td></tr><?php endforeach;?></table></div></section>
<?php include __DIR__.'/../layout/footer.php'; ?>
